"use client";

import { useEffect, useRef, useState } from "react";
import * as THREE from "three";
import proj4 from "proj4";
import { ChunkLoader } from "./three/ChunkLoader";
import { createRenderer } from "./three/Renderer";
import { createCamera } from "./three/Camera";
import { createScene } from "./three/Scene";
import { createControls } from "./three/Controls";
import { setupRaycast } from "./three/Raycast";
import { OverlayInfo } from "./OverlayInfo";

export default function ThreeScene({ settings = {} }) {
  const containerRef = useRef(null);
  const cameraRef = useRef(null);
  const rendererRef = useRef(null);
  const controlsRef = useRef(null);
  const sceneRef = useRef(null);
  const cubeRef = useRef(null);
  const frameRef = useRef(null);
  const updateTimeoutRef = useRef(null);
  const controllerRef = useRef(null);
  const isLoadingRef = useRef(false);

  const loadersRef = useRef(new Map());

  const wgs84 = "EPSG:4326";
  const webMercator = "EPSG:3857";

  const [status, setStatus] = useState({
    chunks: 0,
    meshes: 0,
    features: 0,
    lastQueryMs: 0,
    buildings: 0,
    roads: 0,
    water: 0,
  });

  useEffect(() => {
    const container = containerRef.current;
    if (!container) return;

    const envBase = process.env.NEXT_PUBLIC_API_BASE || "http://127.0.0.1:8000";

    const wgs84 = "EPSG:4326";
    const webMercator = "EPSG:3857";

    const startLon = parseFloat(process.env.NEXT_PUBLIC_STARTLON || "0");
    const startLat = parseFloat(process.env.NEXT_PUBLIC_STARTLAT || "0");
    const [centerX, centerZ] = proj4(wgs84, webMercator, [startLon, startLat]);

    const endpoints = {
      buildings: settings.endpoints?.buildings || `${envBase}/chunk/buildings`,
      roads: settings.endpoints?.roads || `${envBase}/chunk/roads`,
      water: settings.endpoints?.water || `${envBase}/chunk/water`,
    };

    const getLoader = (layerKey, scene, opts = {}) => {
      if (settings.loaders?.[layerKey]) return settings.loaders[layerKey];
      return new ChunkLoader(scene, opts);
    };

    const renderer = createRenderer(container);
    rendererRef.current = renderer;

    const camera = createCamera(container.clientWidth, container.clientHeight);
    camera.fov = 60;
    camera.updateProjectionMatrix();
    cameraRef.current = camera;

    const controls = createControls(camera, renderer.domElement);
    controlsRef.current = controls;

    const { scene, cube } = createScene();
    sceneRef.current = scene;
    cubeRef.current = cube;
    scene.background = new THREE.Color(0xbfd9ff);

    const dirLight = new THREE.DirectionalLight(0xffffff, 1.0);
    dirLight.position.set(1000, 2000, 1000);
    scene.add(dirLight);

    const ambLight = new THREE.AmbientLight(0x666666, 0.8);
    scene.add(ambLight);

    const cleanupRaycast = setupRaycast(
      renderer.domElement,
      camera,
      scene,
      controls,
      container
    );

    camera.position.set(0, 800, 800);
    camera.lookAt(0, 0, 0);
    controls.target.set(0, 0, 0);
    controls.update();

    const buildingsLoader = getLoader("buildings", scene, {
      url: endpoints.buildings,
      centerOffset: [centerX, centerZ],
      layerType: "buildings",
      onProgress: (meta) => {
        setStatus((s) => ({
          ...s,
          buildings: meta.rendered || 0,
          lastQueryMs: meta.queryTimeMs || s.lastQueryMs,
        }));
      },
    });

    const roadsLoader = getLoader("roads", scene, {
      url: endpoints.roads,
      centerOffset: [centerX, centerZ],
      layerType: "roads",
      onProgress: (meta) =>
        setStatus((s) => ({ ...s, roads: meta.rendered || 0 })),
    });

    const waterLoader = getLoader("water", scene, {
      url: endpoints.water,
      centerOffset: [centerX, centerZ],
      layerType: "rivers",
      onProgress: (meta) =>
        setStatus((s) => ({ ...s, water: meta.rendered || 0 })),
    });

    // Weather loader
    const loadWeather = async () => {
      if (typeof createWeatherLoader !== "function") return;
      const weatherLoader = createWeatherLoader(scene, {
        url: `${envBase}/weather/area`,
        centerOffset: [centerX, centerZ],
        minTemp: -20,
        maxTemp: 40,
        barRadius: 10,
        heightScale: 2,
      });

      // Пример области, можно заменить на реальные координаты
      const minLon = startLon - 0.1;
      const minLat = startLat - 0.1;
      const maxLon = startLon + 0.1;
      const maxLat = startLat + 0.1;

      await weatherLoader.loadChunk(minLon, minLat, maxLon, maxLat);
      loadersRef.current.set("weather", weatherLoader);
    };

    loadWeather();

    loadersRef.current.set("buildings", buildingsLoader);
    loadersRef.current.set("roads", roadsLoader);
    loadersRef.current.set("water", waterLoader);

    if (typeof settings.onLoadersReady === "function") {
      try {
        settings.onLoadersReady({
          buildings: buildingsLoader,
          roads: roadsLoader,
          water: waterLoader,
        });
      } catch (e) {
        console.warn("onLoadersReady callback failed:", e);
      }
    }

    const groundGeom = new THREE.PlaneGeometry(500000, 500000, 1, 1);
    const groundMat = new THREE.MeshStandardMaterial({
      color: 0xf0f0f0,
      roughness: 1,
      metalness: 0,
    });
    const ground = new THREE.Mesh(groundGeom, groundMat);
    ground.rotation.x = -Math.PI / 2;
    ground.position.y = -0.5;
    ground.receiveShadow = true;
    scene.add(ground);

    const loop = () => {
      if (!cubeRef.current || !sceneRef.current) return;
      cubeRef.current.rotation.y += 0.005;
      ground.position.x = camera.position.x;
      ground.position.z = camera.position.z;
      controls.update();

      const rLoader = loadersRef.current.get("roads");
      if (rLoader?.meshGroups) {
        for (const group of rLoader.meshGroups.values()) {
          group.traverse((obj) => {
            if (!obj.isLine) return;
            const t = obj.userData.roadType || "unknown";
            const dist = camera.position.distanceTo(obj.position);

            if (["motorway", "trunk", "primary"].includes(t)) {
              const k = THREE.MathUtils.clamp(2000 / dist, 0.4, 2.5);
              obj.material.color.setScalar(0.4 + k * 0.6);
              obj.scale.set(k, k, k);
              obj.visible = true;
            } else if (["footway", "path", "service"].includes(t)) {
              const hideDist = 800;
              obj.visible = dist < hideDist;
              if (obj.visible) {
                const k = THREE.MathUtils.clamp(900 / dist, 0.2, 1.0);
                obj.material.color.setScalar(0.25 + k * 0.3);
                obj.scale.set(k, k, k);
              }
            } else {
              const k = THREE.MathUtils.clamp(1200 / dist, 0.3, 1.3);
              obj.material.color.setScalar(0.3 + k * 0.4);
              obj.scale.set(k, k, k);
              obj.visible = true;
            }
          });
        }
      }

      const hideBuildingsHeight = 15000;
      const bLoader = loadersRef.current.get("buildings");
      if (bLoader?.meshGroups) {
        const visible = camera.position.y < hideBuildingsHeight;
        for (const group of bLoader.meshGroups.values())
          group.visible = visible;
      }

      renderer.render(scene, camera);
      frameRef.current = requestAnimationFrame(loop);
    };
    loop();

    async function updateChunks() {
      if (isLoadingRef.current) return;
      isLoadingRef.current = true;

      if (controllerRef.current) {
        try {
          controllerRef.current.abort();
        } catch (e) {}
      }
      const controller = new AbortController();
      controllerRef.current = controller;

      try {
        const tx = controls.target.x + centerX;
        const tz = controls.target.z + centerZ;
        const [lon, lat] = proj4(webMercator, wgs84, [tx, tz]);

        const tileSize = settings.tileSize || 0.05;
        const viewRadius =
          typeof settings.viewRadius === "number" ? settings.viewRadius : 5;

        const centerTileX = Math.floor(lon / tileSize);
        const centerTileY = Math.floor(lat / tileSize);

        const tilesToLoad = [];
        const activeTiles = new Set();

        for (let dx = -viewRadius; dx <= viewRadius; dx++) {
          for (let dy = -viewRadius; dy <= viewRadius; dy++) {
            const tileX = centerTileX + dx;
            const tileY = centerTileY + dy;

            const minLon = tileX * tileSize;
            const minLat = tileY * tileSize;
            const maxLon = (tileX + 1) * tileSize;
            const maxLat = (tileY + 1) * tileSize;

            const tileKey = `${tileX}_${tileY}`;
            activeTiles.add(tileKey);

            tilesToLoad.push({ minLon, minLat, maxLon, maxLat, key: tileKey });
          }
        }

        const batchPromises = tilesToLoad.map((tile) => {
          const optsBase = {
            signal: controller.signal,
            useCache: true,
            keyHint: tile.key,
          };
          return Promise.all([
            (loadersRef.current.get("buildings") || buildingsLoader).loadChunk(
              tile.minLon,
              tile.minLat,
              tile.maxLon,
              tile.maxLat,
              { ...optsBase, simplify: 2.0, keyHint: `buildings_${tile.key}` }
            ),
            (loadersRef.current.get("roads") || roadsLoader).loadChunk(
              tile.minLon,
              tile.minLat,
              tile.maxLon,
              tile.maxLat,
              { ...optsBase, simplify: 0.5, keyHint: `roads_${tile.key}` }
            ),
            (loadersRef.current.get("water") || waterLoader).loadChunk(
              tile.minLon,
              tile.minLat,
              tile.maxLon,
              tile.maxLat,
              { ...optsBase, simplify: 0.0, keyHint: `water_${tile.key}` }
            ),
          ]);
        });

        await Promise.all(batchPromises);

        const cleanupUnused = (loader, layerName) => {
          if (!loader?.meshGroups) return;
          for (const key of loader.meshGroups.keys()) {
            const re = new RegExp(`^${layerName}_(-?\\d+)_(-?\\d+)$`);
            const match = key.match(re);
            if (match && !activeTiles.has(`${match[1]}_${match[2]}`)) {
              loader.removeChunk?.(key);
            }
          }
        };

        cleanupUnused(buildingsLoader, "buildings");
        cleanupUnused(roadsLoader, "roads");
        cleanupUnused(waterLoader, "water");
      } catch (e) {
        if (e?.name !== "AbortError")
          console.error("[Scene] loadChunk error:", e);
      } finally {
        isLoadingRef.current = false;
      }
    }

    const debouncedUpdate = () => {
      if (updateTimeoutRef.current) clearTimeout(updateTimeoutRef.current);
      updateTimeoutRef.current = setTimeout(updateChunks, 250);
    };

    controls.addEventListener("change", debouncedUpdate);
    updateChunks();

    const handleResize = () => {
      renderer.setSize(container.clientWidth, container.clientHeight);
      camera.aspect = container.clientWidth / container.clientHeight;
      camera.updateProjectionMatrix();
    };
    window.addEventListener("resize", handleResize);
    container.appendChild(renderer.domElement);

    return () => {
      cancelAnimationFrame(frameRef.current);
      clearTimeout(updateTimeoutRef.current);
      controls.removeEventListener("change", debouncedUpdate);
      window.removeEventListener("resize", handleResize);
      try {
        cleanupRaycast();
      } catch (e) {}
      try {
        controllerRef.current?.abort();
      } catch (e) {}

      for (const loader of loadersRef.current.values()) loader.clearAll?.();
      try {
        if (renderer.domElement && container.contains(renderer.domElement))
          container.removeChild(renderer.domElement);
      } catch (e) {}
      try {
        renderer.dispose();
      } catch (e) {}
      try {
        cube?.geometry.dispose();
        cube?.material.dispose();
      } catch (e) {}
      try {
        groundGeom.dispose();
        groundMat.dispose();
      } catch (e) {}

      rendererRef.current = null;
      cameraRef.current = null;
      controlsRef.current = null;
      sceneRef.current = null;
    };
  }, []);

  return (
    <div className="w-full h-full relative">
      <div ref={containerRef} className="w-full h-full" />
    </div>
  );
}
